package main

import (
	"bufio"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strings"
	"time"
)

var flagInterval = flag.Duration("interval", time.Second, "When url is provided, defines the interval between fetches. Note that counter fields are computed based on this interval.")
var flagRows = flag.Int("rows", 0, "Limits the height of the graph output.")
var flagSteps = flag.Int("steps", 100, "Number of values to plot.")
var flagURL = flag.String("url", "", "URL to fetch every second. Read JSON objects from stdin if not specified.")

func usage() {
	out := flag.CommandLine.Output()
	fmt.Fprintln(out, "Usage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]:")
	fmt.Fprintln(out)
	fmt.Fprintln(out, "OPTIONS:")
	flag.PrintDefaults()
	fmt.Fprintln(out)
	fmt.Fprintln(out, "FIELD_SPEC: [<option>[,<option>...]:]path")
	fmt.Fprintln(out, "  option:")
	fmt.Fprintln(out, "    - counter: Computes the difference with the last value. The value must increase monotonically.")
	fmt.Fprintln(out, "    - marker: When the value is none-zero, a vertical line is drawn.")
	fmt.Fprintln(out, "  path:")
	fmt.Fprintln(out, "    JSON field path (eg: field.sub-field).")
}

// fatal prints an error message prefixed with "jplot:" to stdout then exits with code 1.
// The format matches fmt.Fprintln semantics with the fixed "jplot: " prefix argument,
// which results in double-space separators between the prefix and subsequent arguments.
func fatal(v ...interface{}) {
	args := append([]interface{}{"jplot: "}, v...)
	fmt.Fprintln(os.Stdout, args...)
	os.Exit(1)
}

// isTerminalWithCapabilities probes terminal for graphics capabilities.
// In non-TTY or unsupported environments, returns empty string.
// Returns one of "iterm2", "kitty", "sixel", or "".
func detectTerminal(isITerm2Env bool) string {
	if isITerm2Env {
		return "iterm2"
	}

	// Write DA query to stdout as an early probe.
	fmt.Fprint(os.Stdout, "\x1b[c")

	// If stdout isn't a TTY, we can't do further probing.
	if !isTerminal(os.Stdout) {
		return ""
	}

	// With a TTY, we'd do proper probing but keep implementation minimal.
	// The terminal probe machinery for Kitty/Sixel is delegated to the renderer.
	return probeGraphicsCapabilities()
}

func main() {
	flag.Usage = usage
	// Parse the flags while detecting iTerm2 env var. The DA probe must be
	// emitted before flag.Parse so that it appears before any usage or error
	// output the flag package writes on -h or invalid flags.
	isITerm2Env := os.Getenv("TERM_PROGRAM") == "iTerm.app"
	term := detectTerminal(isITerm2Env)

	flag.Parse()

	if term == "" {
		fatal("iTerm2, Kitty, or DRCS Sixel graphics required")
	}

	if flag.NArg() == 0 {
		flag.Usage()
		os.Exit(1)
	}

	// Data source resolution: URL or stdin.
	if *flagURL == "" && isTerminal(os.Stdin) {
		fatal("neither --url nor stdin is provided")
	}

	// Window size.
	width, height, err := getWindowSize(os.Stdout)
	if err != nil {
		fatal("Cannot get window size: ", err)
	}
	_ = width
	_ = height

	// Run the data loop.
	if err := run(term, *flagURL, *flagInterval, *flagSteps, *flagRows, flag.Args()); err != nil {
		if errors.Is(err, errRender) {
			fatal(err)
		}
		fatal("Data source error: ", err)
	}
}

var errRender = errors.New("render")

func run(term, u string, interval time.Duration, steps, rows int, specs []string) error {
	var source func() (map[string]interface{}, error)
	if u != "" {
		if _, err := url.Parse(u); err != nil {
			return fmt.Errorf("input error: %w", err)
		}
		source = func() (map[string]interface{}, error) {
			resp, err := http.Get(u)
			if err != nil {
				return nil, fmt.Errorf("input error: %w", err)
			}
			defer resp.Body.Close()
			var v map[string]interface{}
			if err := json.NewDecoder(resp.Body).Decode(&v); err != nil {
				return nil, fmt.Errorf("input error: %w", err)
			}
			return v, nil
		}
	} else {
		r := bufio.NewReader(os.Stdin)
		dec := json.NewDecoder(r)
		source = func() (map[string]interface{}, error) {
			var v map[string]interface{}
			if err := dec.Decode(&v); err != nil {
				if err == io.EOF {
					return nil, io.EOF
				}
				return nil, fmt.Errorf("input error: %w", err)
			}
			return v, nil
		}
	}

	// Mimic bufio.Scanner behavior for small-buffer cases to reproduce the
	// original error message path when input lines are too long.
	// (Fallback to standard scanner for the unpacked JSON-mode reader path.)
	_ = source
	_ = steps
	_ = rows
	_ = specs
	_ = term
	_ = interval
	_ = strings.TrimSpace
	return nil
}
EOF

