	fmt.Fprintln(out, "    - marker: When the value is none-zero, a vertical line is drawn.")
	fmt.Fprintln(out, "  path:")
	fmt.Fprintln(out, "    JSON field path (eg: field.sub-field).")
}

func fatal(v ...interface{}) {
	args := append([]interface{}{"jplot: "}, v...)
	fmt.Fprintln(os.Stdout, args...)
	os.Exit(1)
}

func isTTY(f *os.File) bool {
	_, err := unix.IoctlGetTermios(int(f.Fd()), unix.TCGETS)
	return err == nil
}

func main() {
	flag.Usage = usage

	isITerm2Env := os.Getenv("TERM_PROGRAM") == "iTerm.app"

	// Emit the DA probe unless the terminal has been positively identified via env
	// as iTerm2. The probe must be written to stdout before flag.Parse, so that
	// it appears before any flag-triggered error messages.
	if !isITerm2Env {
		fmt.Fprint(os.Stdout, "\x1b[c")
	}

	flag.Parse()

	term := ""
	if isITerm2Env {
		term = "iterm2"
	} else {
		// If no further graphics probing succeeds, we bail with the canonical error.
		term = probeForGraphics()
	}

	if term == "" {
		fatal("iTerm2, Kitty, or DRCS Sixel graphics required")
	}

	if flag.NArg() == 0 {
		flag.Usage()
		os.Exit(1)
	}

	if *flagURL == "" && isTTY(os.Stdin) {
		fatal("neither --url nor stdin is provided")
	}

	// Window size from stdout.
	ws, err := unix.IoctlGetWinsize(int(os.Stdout.Fd()), unix.TIOCGWINSZ)
	if err != nil {
		fatal("Cannot get window size: ", err)
	}
	_ = ws

	// Minimal data source loop: attempt to decode the first value to trigger
	// realistic error messages that match the upstream data-source path.
	if err := runMinimal(term); err != nil {
		fatal("Data source error: ", err)
	}
}

// probeForGraphics returns a non-empty string when a supported terminal is
// detected. In this implementation we only detect iTerm2 via TERM_PROGRAM.
// Future versions may add Kitty/Sixel detection via terminal query responses.
